package android.content; public class ContentValues {private final java.util.LinkedHashMap<String,Object> values=new java.util.LinkedHashMap<>();public void put(String k,String v){values.put(k,v);}public void put(String k,Integer v){values.put(k,v);}public void put(String k,Long v){values.put(k,v);}public void put(String k,Boolean v){values.put(k,v==null?null:v?1:0);}public void put(String k,byte[] v){values.put(k,v);}public void putNull(String k){values.put(k,null);}public java.util.Set<java.util.Map.Entry<String,Object>> valueSet(){return values.entrySet();}public int size(){return values.size();}}